CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_program_with_structure(p_program jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner_id uuid := auth.uid();
  v_program_id uuid;
  v_week_id uuid;
  v_workout_id uuid;
  v_workout_exercise_id uuid;
  v_week jsonb;
  v_workout jsonb;
  v_exercise jsonb;
  v_set jsonb;
  v_workouts jsonb;
  v_exercises jsonb;
  v_sets jsonb;
  v_weeks jsonb := p_program -> 'weeks';
  v_week_idx bigint;
  v_workout_idx bigint;
  v_exercise_idx bigint;
  v_set_idx bigint;
  v_name text := btrim(coalesce(p_program ->> 'name', ''));
  v_workout_name text;
  v_week_count integer;
  v_structure_mode text := coalesce(nullif(btrim(p_program ->> 'structure_mode'), ''), 'legacy_weeks');
  v_cycle_repeat_count integer := 1;
  v_exercise_id uuid;
  v_exercise_name_snapshot text;
  v_prescription_snapshot text;
  v_reps integer;
  v_rest_days_after integer;
begin
  if v_owner_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_program is null or jsonb_typeof(p_program) <> 'object' then raise exception 'Program payload must be an object' using errcode='22023'; end if;
  if v_name = '' or char_length(v_name) > 80 then raise exception 'Program name must contain 1 to 80 characters' using errcode='22023'; end if;
  if v_structure_mode not in ('legacy_weeks','cycle') then raise exception 'Invalid structure mode' using errcode='22023'; end if;

  begin v_week_count := (p_program ->> 'week_count')::integer;
  exception when others then raise exception 'Week count must be an integer' using errcode='22023'; end;
  begin v_cycle_repeat_count := coalesce(nullif(p_program ->> 'cycle_repeat_count',''),'1')::integer;
  exception when others then raise exception 'Cycle repeat count must be an integer' using errcode='22023'; end;

  if v_week_count < 1 or v_week_count > 52 then raise exception 'Week count must be between 1 and 52' using errcode='22023'; end if;
  if v_cycle_repeat_count < 1 or v_cycle_repeat_count > 52 then raise exception 'Cycle repeat count must be between 1 and 52' using errcode='22023'; end if;
  if jsonb_typeof(v_weeks) <> 'array' then raise exception 'Weeks must be an array' using errcode='22023'; end if;
  if v_structure_mode='cycle' and jsonb_array_length(v_weeks) <> 1 then raise exception 'Cycle programs must contain exactly one template cycle' using errcode='22023'; end if;
  if v_structure_mode='legacy_weeks' and jsonb_array_length(v_weeks) <> v_week_count then raise exception 'Weeks array must match week_count' using errcode='22023'; end if;

  insert into public.programs (
    owner_id,name,description,week_count,categories,training_place,equipment,level,status,
    structure_mode,cycle_repeat_count
  ) values (
    v_owner_id,v_name,nullif(btrim(coalesce(p_program->>'description','')),''),
    case when v_structure_mode='cycle' then 1 else v_week_count end,
    case when jsonb_typeof(p_program->'categories')='array' then array(select jsonb_array_elements_text(p_program->'categories')) else '{}'::text[] end,
    nullif(btrim(coalesce(p_program->>'training_place','')),''),
    nullif(btrim(coalesce(p_program->>'equipment','')),''),
    nullif(btrim(coalesce(p_program->>'level','')),''),
    'active',v_structure_mode,v_cycle_repeat_count
  ) returning id into v_program_id;

  for v_week,v_week_idx in select value,ordinality from jsonb_array_elements(v_weeks) with ordinality loop
    v_workouts := v_week->'workouts';
    if jsonb_typeof(v_workouts)<>'array' or jsonb_array_length(v_workouts)=0 then raise exception 'Every cycle/week must contain at least one workout' using errcode='22023'; end if;
    insert into public.program_weeks(program_id,week_number,position)
    values(v_program_id,v_week_idx::smallint,v_week_idx::smallint) returning id into v_week_id;

    for v_workout,v_workout_idx in select value,ordinality from jsonb_array_elements(v_workouts) with ordinality loop
      v_workout_name := btrim(coalesce(v_workout->>'name',''));
      v_exercises := v_workout->'exercises';
      begin v_rest_days_after := coalesce(nullif(v_workout->>'rest_days_after',''),'1')::integer;
      exception when others then raise exception 'Rest days after workout must be an integer' using errcode='22023'; end;
      if v_workout_name='' or char_length(v_workout_name)>80 then raise exception 'Workout name must contain 1 to 80 characters' using errcode='22023'; end if;
      if v_rest_days_after<0 or v_rest_days_after>30 then raise exception 'Rest days after workout must be between 0 and 30' using errcode='22023'; end if;
      if jsonb_typeof(v_exercises)<>'array' or jsonb_array_length(v_exercises)=0 then raise exception 'Every workout must contain at least one exercise' using errcode='22023'; end if;
      insert into public.program_workouts(week_id,name,position,rest_days_after)
      values(v_week_id,v_workout_name,v_workout_idx::smallint,v_rest_days_after::smallint) returning id into v_workout_id;

      for v_exercise,v_exercise_idx in select value,ordinality from jsonb_array_elements(v_exercises) with ordinality loop
        v_exercise_id := null;
        if nullif(btrim(coalesce(v_exercise->>'exercise_id','')),'') is not null then
          begin v_exercise_id := (v_exercise->>'exercise_id')::uuid;
          exception when others then raise exception 'Invalid exercise id' using errcode='22023'; end;
        end if;
        v_exercise_name_snapshot := nullif(btrim(coalesce(v_exercise->>'exercise_name_snapshot',v_exercise->>'name','')),'');
        v_prescription_snapshot := nullif(btrim(coalesce(v_exercise->>'prescription_snapshot',v_exercise->>'prescription','')),'');
        if v_exercise_id is null and v_exercise_name_snapshot is null then raise exception 'Exercise id or snapshot name is required' using errcode='22023'; end if;

        insert into public.program_workout_exercises(workout_id,exercise_id,exercise_name_snapshot,prescription_snapshot,position)
        values(v_workout_id,v_exercise_id,v_exercise_name_snapshot,v_prescription_snapshot,v_exercise_idx::smallint)
        returning id into v_workout_exercise_id;

        v_sets := coalesce(v_exercise->'sets','[]'::jsonb);
        if jsonb_typeof(v_sets)<>'array' then raise exception 'Exercise sets must be an array' using errcode='22023'; end if;
        for v_set,v_set_idx in select value,ordinality from jsonb_array_elements(v_sets) with ordinality loop
          if v_set->>'reps' is null or btrim(v_set->>'reps')='' then v_reps:=null;
          else
            begin v_reps := (v_set->>'reps')::integer;
            exception when others then raise exception 'Reps must be an integer' using errcode='22023'; end;
            if v_reps<1 or v_reps>999 then raise exception 'Reps must be between 1 and 999' using errcode='22023'; end if;
          end if;
          insert into public.program_exercise_sets(workout_exercise_id,set_number,reps)
          values(v_workout_exercise_id,v_set_idx::smallint,v_reps);
        end loop;
      end loop;
    end loop;
  end loop;
  return v_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_program_with_structure(p_program_id uuid, p_program jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner_id uuid := auth.uid();
  v_week_id uuid; v_workout_id uuid; v_workout_exercise_id uuid;
  v_week jsonb; v_workout jsonb; v_exercise jsonb; v_set jsonb;
  v_workouts jsonb; v_exercises jsonb; v_sets jsonb; v_weeks jsonb := p_program->'weeks';
  v_week_idx bigint; v_workout_idx bigint; v_exercise_idx bigint; v_set_idx bigint;
  v_name text := btrim(coalesce(p_program->>'name','')); v_workout_name text;
  v_week_count integer; v_structure_mode text := coalesce(nullif(btrim(p_program->>'structure_mode'),''),'legacy_weeks');
  v_cycle_repeat_count integer := 1; v_exercise_id uuid; v_exercise_name_snapshot text; v_prescription_snapshot text;
  v_reps integer; v_rest_days_after integer;
begin
  if v_owner_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_program is null or jsonb_typeof(p_program)<>'object' then raise exception 'Program payload must be an object' using errcode='22023'; end if;
  if v_name='' or char_length(v_name)>80 then raise exception 'Program name must contain 1 to 80 characters' using errcode='22023'; end if;
  if v_structure_mode not in ('legacy_weeks','cycle') then raise exception 'Invalid structure mode' using errcode='22023'; end if;
  begin v_week_count := (p_program->>'week_count')::integer; exception when others then raise exception 'Week count must be an integer' using errcode='22023'; end;
  begin v_cycle_repeat_count := coalesce(nullif(p_program->>'cycle_repeat_count',''),'1')::integer; exception when others then raise exception 'Cycle repeat count must be an integer' using errcode='22023'; end;
  if v_week_count<1 or v_week_count>52 then raise exception 'Week count must be between 1 and 52' using errcode='22023'; end if;
  if v_cycle_repeat_count<1 or v_cycle_repeat_count>52 then raise exception 'Cycle repeat count must be between 1 and 52' using errcode='22023'; end if;
  if jsonb_typeof(v_weeks)<>'array' then raise exception 'Weeks must be an array' using errcode='22023'; end if;
  if v_structure_mode='cycle' and jsonb_array_length(v_weeks)<>1 then raise exception 'Cycle programs must contain exactly one template cycle' using errcode='22023'; end if;
  if v_structure_mode='legacy_weeks' and jsonb_array_length(v_weeks)<>v_week_count then raise exception 'Weeks array must match week_count' using errcode='22023'; end if;

  update public.programs set
    name=v_name,
    description=nullif(btrim(coalesce(p_program->>'description','')),''),
    week_count=case when v_structure_mode='cycle' then 1 else v_week_count end,
    categories=case when jsonb_typeof(p_program->'categories')='array' then array(select jsonb_array_elements_text(p_program->'categories')) else '{}'::text[] end,
    training_place=nullif(btrim(coalesce(p_program->>'training_place','')),''),
    equipment=nullif(btrim(coalesce(p_program->>'equipment','')),''),
    level=nullif(btrim(coalesce(p_program->>'level','')),''),
    structure_mode=v_structure_mode,
    cycle_repeat_count=v_cycle_repeat_count,
    updated_at=now()
  where id=p_program_id and owner_id=v_owner_id;
  if not found then raise exception 'Program not found or access denied' using errcode='42501'; end if;

  delete from public.program_weeks where program_id=p_program_id;
  for v_week,v_week_idx in select value,ordinality from jsonb_array_elements(v_weeks) with ordinality loop
    v_workouts:=v_week->'workouts';
    if jsonb_typeof(v_workouts)<>'array' or jsonb_array_length(v_workouts)=0 then raise exception 'Every cycle/week must contain at least one workout' using errcode='22023'; end if;
    insert into public.program_weeks(program_id,week_number,position) values(p_program_id,v_week_idx::smallint,v_week_idx::smallint) returning id into v_week_id;
    for v_workout,v_workout_idx in select value,ordinality from jsonb_array_elements(v_workouts) with ordinality loop
      v_workout_name:=btrim(coalesce(v_workout->>'name','')); v_exercises:=v_workout->'exercises';
      begin v_rest_days_after:=coalesce(nullif(v_workout->>'rest_days_after',''),'1')::integer; exception when others then raise exception 'Rest days after workout must be an integer' using errcode='22023'; end;
      if v_workout_name='' or char_length(v_workout_name)>80 then raise exception 'Workout name must contain 1 to 80 characters' using errcode='22023'; end if;
      if v_rest_days_after<0 or v_rest_days_after>30 then raise exception 'Rest days after workout must be between 0 and 30' using errcode='22023'; end if;
      if jsonb_typeof(v_exercises)<>'array' or jsonb_array_length(v_exercises)=0 then raise exception 'Every workout must contain at least one exercise' using errcode='22023'; end if;
      insert into public.program_workouts(week_id,name,position,rest_days_after) values(v_week_id,v_workout_name,v_workout_idx::smallint,v_rest_days_after::smallint) returning id into v_workout_id;
      for v_exercise,v_exercise_idx in select value,ordinality from jsonb_array_elements(v_exercises) with ordinality loop
        v_exercise_id:=null;
        if nullif(btrim(coalesce(v_exercise->>'exercise_id','')),'') is not null then begin v_exercise_id:=(v_exercise->>'exercise_id')::uuid; exception when others then raise exception 'Invalid exercise id' using errcode='22023'; end; end if;
        v_exercise_name_snapshot:=nullif(btrim(coalesce(v_exercise->>'exercise_name_snapshot',v_exercise->>'name','')),'');
        v_prescription_snapshot:=nullif(btrim(coalesce(v_exercise->>'prescription_snapshot',v_exercise->>'prescription','')),'');
        if v_exercise_id is null and v_exercise_name_snapshot is null then raise exception 'Exercise id or snapshot name is required' using errcode='22023'; end if;
        insert into public.program_workout_exercises(workout_id,exercise_id,exercise_name_snapshot,prescription_snapshot,position)
        values(v_workout_id,v_exercise_id,v_exercise_name_snapshot,v_prescription_snapshot,v_exercise_idx::smallint) returning id into v_workout_exercise_id;
        v_sets:=coalesce(v_exercise->'sets','[]'::jsonb);
        if jsonb_typeof(v_sets)<>'array' then raise exception 'Exercise sets must be an array' using errcode='22023'; end if;
        for v_set,v_set_idx in select value,ordinality from jsonb_array_elements(v_sets) with ordinality loop
          if v_set->>'reps' is null or btrim(v_set->>'reps')='' then v_reps:=null; else begin v_reps:=(v_set->>'reps')::integer; exception when others then raise exception 'Reps must be an integer' using errcode='22023'; end; if v_reps<1 or v_reps>999 then raise exception 'Reps must be between 1 and 999' using errcode='22023'; end if; end if;
          insert into public.program_exercise_sets(workout_exercise_id,set_number,reps) values(v_workout_exercise_id,v_set_idx::smallint,v_reps);
        end loop;
      end loop;
    end loop;
  end loop;
  return p_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_program_with_schedule(p_program jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_program_id uuid; v_schedule_mode text:=coalesce(nullif(btrim(p_program->>'schedule_mode'),''),'custom');
begin
  if v_schedule_mode not in ('custom','weekly_mwf','weekly_tts','cycle_2_2') then raise exception 'Invalid schedule mode' using errcode='22023'; end if;
  v_program_id:=public.create_program_with_structure(p_program);
  update public.programs set schedule_mode=v_schedule_mode,updated_at=now() where id=v_program_id and owner_id=(select auth.uid());
  if not found then raise exception 'Program not found or access denied' using errcode='42501'; end if;
  return v_program_id;
end; $function$

CREATE OR REPLACE FUNCTION public.complete_workout(p_workout_session_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_scheduled_workout_id uuid;
  v_user_program_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;

  update public.workout_sessions ws
  set status='completed',
      ended_at=now(),
      active_duration_seconds = ws.active_duration_seconds + case when ws.paused_at is null then greatest(0, floor(extract(epoch from (now() - ws.started_at)))::integer) else 0 end,
      paused_at=null,
      updated_at=now()
  where ws.id=p_workout_session_id and ws.user_id=v_user_id and ws.status='active'
  returning ws.scheduled_workout_id into v_scheduled_workout_id;

  if v_scheduled_workout_id is null then raise exception 'Active workout session not found or access denied' using errcode='P0002'; end if;

  update public.scheduled_workouts sw set status='completed' where sw.id=v_scheduled_workout_id returning sw.user_program_id into v_user_program_id;

  if v_user_program_id is not null and not exists (
    select 1 from public.scheduled_workouts sw where sw.user_program_id=v_user_program_id and sw.status='scheduled'
  ) then
    update public.user_programs up set status='completed', completed_at=now(), updated_at=now()
    where up.id=v_user_program_id and up.user_id=v_user_id and up.status in ('active','paused');
  end if;
  return p_workout_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.abandon_workout(p_workout_session_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_scheduled_workout_id uuid;
  v_user_program_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  update public.workout_sessions ws
  set status = 'abandoned',
      ended_at = now(),
      active_duration_seconds = greatest(
        ws.active_duration_seconds,
        floor(extract(epoch from (now() - ws.started_at)))::integer
      ),
      updated_at = now()
  where ws.id = p_workout_session_id
    and ws.user_id = v_user_id
    and ws.status = 'active'
  returning ws.scheduled_workout_id into v_scheduled_workout_id;

  if v_scheduled_workout_id is null then
    raise exception 'Active workout session not found or access denied' using errcode = 'P0002';
  end if;

  update public.scheduled_workouts sw
  set status = 'skipped'
  where sw.id = v_scheduled_workout_id
  returning sw.user_program_id into v_user_program_id;

  if v_user_program_id is not null and not exists (
    select 1
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.status = 'scheduled'
  ) then
    update public.user_programs up
    set status = 'completed',
        completed_at = now(),
        updated_at = now()
    where up.id = v_user_program_id
      and up.user_id = v_user_id
      and up.status in ('active','paused');
  end if;

  return p_workout_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.adopt_catalog_program(p_catalog_program_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid:=auth.uid(); v_catalog public.catalog_programs%rowtype; v_program_id uuid; v_week_id uuid; v_workout_id uuid; v_workout_exercise_id uuid;
  v_workout jsonb; v_exercise jsonb; v_workout_pos bigint; v_exercise_pos bigint; v_exercise_id uuid; v_name text; v_prescription text;
  v_set_count integer; v_reps integer; v_match text[]; v_set_number integer; v_cycle_workouts jsonb;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  select * into v_catalog from public.catalog_programs where id=p_catalog_program_id and published=true;
  if v_catalog.id is null then raise exception 'Catalog program not found or unavailable' using errcode='P0002'; end if;
  select p.id into v_program_id from public.programs p where p.owner_id=v_user_id and p.source_catalog_program_id=p_catalog_program_id and p.status<>'archived' limit 1;
  if v_program_id is not null then return v_program_id; end if;

  v_cycle_workouts:=coalesce(v_catalog.source_payload->'cycle'->'workouts','[]'::jsonb);
  if jsonb_typeof(v_cycle_workouts)<>'array' or jsonb_array_length(v_cycle_workouts)=0 then raise exception 'Catalog program has no cycle workouts' using errcode='22023'; end if;
  insert into public.programs(owner_id,name,description,week_count,categories,training_place,equipment,level,status,schedule_mode,source_catalog_program_id,structure_mode,cycle_repeat_count)
  values(v_user_id,left(v_catalog.name,80),v_catalog.description,1,v_catalog.categories,v_catalog.training_place,v_catalog.equipment,v_catalog.level,'active','custom',v_catalog.id,'cycle',1)
  returning id into v_program_id;
  insert into public.program_weeks(program_id,week_number,position) values(v_program_id,1,1) returning id into v_week_id;

  for v_workout,v_workout_pos in select value,ordinality from jsonb_array_elements(v_cycle_workouts) with ordinality loop
    insert into public.program_workouts(week_id,name,position,rest_days_after)
    values(v_week_id,left(coalesce(nullif(btrim(v_workout->>'name'),''),'Тренировка '||v_workout_pos),80),v_workout_pos::smallint,1) returning id into v_workout_id;
    for v_exercise,v_exercise_pos in select value,ordinality from jsonb_array_elements(coalesce(v_workout->'exercises','[]'::jsonb)) with ordinality loop
      v_name:=nullif(btrim(v_exercise->>'name'),''); v_prescription:=nullif(btrim(v_exercise->>'prescription'),''); if v_name is null then continue; end if;
      select e.id into v_exercise_id from public.exercises e where lower(btrim(e.name))=lower(v_name) order by e.id limit 1;
      insert into public.program_workout_exercises(workout_id,exercise_id,exercise_name_snapshot,prescription_snapshot,position)
      values(v_workout_id,v_exercise_id,v_name,v_prescription,v_exercise_pos::smallint) returning id into v_workout_exercise_id;
      v_set_count:=1; v_reps:=null;
      if v_prescription is not null then
        v_match:=regexp_match(v_prescription,'(\d+)\s*[\*xх×]\s*(\d+)','i');
        if v_match is not null then v_set_count:=greatest(1,least(20,v_match[1]::integer)); v_reps:=greatest(1,least(999,v_match[2]::integer));
        else
          v_match:=regexp_match(v_prescription,'(\d+)\s*(?:подход(?:а|ов)?|круг(?:а|ов)?)','i'); if v_match is not null then v_set_count:=greatest(1,least(20,v_match[1]::integer)); end if;
          v_match:=regexp_match(v_prescription,'по\s*(\d+)','i');
          if v_match is not null then v_reps:=greatest(1,least(999,v_match[1]::integer));
          elsif v_prescription~'^\s*\d+\s*-\s*\d+' then v_match:=regexp_match(v_prescription,'^\s*(\d+)'); v_reps:=greatest(1,least(999,v_match[1]::integer));
          elsif v_prescription~*'^\s*\d+\s*(?:$|раз|повтор|повт|шаг)' then v_match:=regexp_match(v_prescription,'^\s*(\d+)'); v_reps:=greatest(1,least(999,v_match[1]::integer)); end if;
        end if;
      end if;
      for v_set_number in 1..v_set_count loop insert into public.program_exercise_sets(workout_exercise_id,set_number,reps) values(v_workout_exercise_id,v_set_number::smallint,v_reps); end loop;
      v_exercise_id:=null;
    end loop;
  end loop;
  return v_program_id;
end; $function$

CREATE OR REPLACE FUNCTION public.start_workout(p_scheduled_workout_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_session_id uuid;
  v_session_exercise_id uuid;
  v_scheduled record;
  v_exercise record;
  v_set record;
  v_set_count integer;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;

  select sw.id, sw.status, sw.scheduled_date, up.status as program_status into v_scheduled
  from public.scheduled_workouts sw join public.user_programs up on up.id=sw.user_program_id
  where sw.id=p_scheduled_workout_id and up.user_id=v_user_id;
  if v_scheduled.id is null then raise exception 'Scheduled workout not found or access denied' using errcode='P0002'; end if;
  if v_scheduled.program_status <> 'active' then raise exception 'Program is not active' using errcode='22023'; end if;

  select ws.id into v_session_id from public.workout_sessions ws
  where ws.user_id=v_user_id and ws.scheduled_workout_id=p_scheduled_workout_id and ws.status='active' limit 1;
  if v_session_id is not null then return v_session_id; end if;
  if exists(select 1 from public.workout_sessions ws where ws.user_id=v_user_id and ws.status='active') then
    raise exception 'Another workout is already active' using errcode='23505';
  end if;
  if v_scheduled.scheduled_date > current_date then raise exception 'Future workout cannot be started' using errcode='22023'; end if;
  if v_scheduled.status='completed' or exists(select 1 from public.workout_sessions ws where ws.user_id=v_user_id and ws.scheduled_workout_id=p_scheduled_workout_id and ws.status='completed') then
    raise exception 'Workout is already completed' using errcode='23505';
  end if;
  if v_scheduled.status in ('skipped','cancelled') then raise exception 'Skipped or cancelled workout cannot be started' using errcode='22023'; end if;

  insert into public.workout_sessions(user_id,scheduled_workout_id,status,paused_at)
  values(v_user_id,p_scheduled_workout_id,'active',null) returning id into v_session_id;

  for v_exercise in
    select swe.id source_id, swe.exercise_id, swe.exercise_name_snapshot, swe.prescription_snapshot, swe.position
    from public.scheduled_workout_exercises swe where swe.scheduled_workout_id=p_scheduled_workout_id order by swe.position
  loop
    insert into public.workout_session_exercises(workout_session_id,source_scheduled_workout_exercise_id,exercise_id,exercise_name_snapshot,prescription_snapshot,position)
    values(v_session_id,v_exercise.source_id,v_exercise.exercise_id,v_exercise.exercise_name_snapshot,v_exercise.prescription_snapshot,v_exercise.position)
    returning id into v_session_exercise_id;
    v_set_count := 0;
    for v_set in select ss.id source_id, ss.set_number, ss.planned_reps from public.scheduled_sets ss where ss.scheduled_workout_exercise_id=v_exercise.source_id order by ss.set_number
    loop
      v_set_count := v_set_count + 1;
      insert into public.performed_sets(workout_session_exercise_id,source_scheduled_set_id,set_number,set_type,planned_reps,reps)
      values(v_session_exercise_id,v_set.source_id,v_set.set_number,'working',v_set.planned_reps,v_set.planned_reps);
    end loop;
    if v_set_count=0 then insert into public.performed_sets(workout_session_exercise_id,set_number,set_type) values(v_session_exercise_id,1,'working'); end if;
  end loop;
  return v_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_program_with_schedule(p_program_id uuid, p_program jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid:=auth.uid(); v_program_id uuid; v_schedule_mode text:=coalesce(nullif(btrim(p_program->>'schedule_mode'),''),'custom');
  v_user_program record; v_scheduled record; v_last_fixed_sequence integer; v_last_fixed_date date; v_first_future_sequence integer; v_first_future_date date;
  v_current_date date; v_new_start_date date; v_rest_days_after integer; v_template_count integer; v_template_index integer; v_structure_mode text;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if v_schedule_mode not in ('custom','weekly_mwf','weekly_tts','cycle_2_2') then raise exception 'Invalid schedule mode' using errcode='22023'; end if;
  v_program_id:=public.update_program_with_structure(p_program_id,p_program);
  update public.programs set schedule_mode=v_schedule_mode,updated_at=now() where id=v_program_id and owner_id=v_user_id;
  if not found then raise exception 'Program not found or access denied' using errcode='42501'; end if;
  select structure_mode into v_structure_mode from public.programs where id=v_program_id;
  select count(*) into v_template_count from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id where pw.program_id=v_program_id;

  for v_user_program in select up.id,up.start_date from public.user_programs up where up.user_id=v_user_id and up.program_id=v_program_id and up.status in ('active','paused') loop
    v_last_fixed_sequence:=null; v_last_fixed_date:=null; v_first_future_sequence:=null; v_first_future_date:=null; v_new_start_date:=null;
    select sw.sequence_number,sw.scheduled_date into v_last_fixed_sequence,v_last_fixed_date from public.scheduled_workouts sw
    where sw.user_program_id=v_user_program.id and (sw.scheduled_date<current_date or sw.status in ('completed','skipped')) order by sw.sequence_number desc limit 1;
    select sw.sequence_number,sw.scheduled_date into v_first_future_sequence,v_first_future_date from public.scheduled_workouts sw
    where sw.user_program_id=v_user_program.id and sw.status='scheduled' and sw.scheduled_date>=current_date and (v_last_fixed_sequence is null or sw.sequence_number>v_last_fixed_sequence)
    order by sw.sequence_number limit 1;
    if v_first_future_sequence is null then continue; end if;

    if v_last_fixed_sequence is null then
      v_current_date:=case when v_first_future_sequence=1 then greatest(v_user_program.start_date,current_date) else greatest(v_first_future_date,current_date) end;
    else
      v_current_date:=v_last_fixed_date;
      if v_schedule_mode='weekly_mwf' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (1,3,5); end loop;
      elsif v_schedule_mode='weekly_tts' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (2,4,6); end loop;
      elsif v_schedule_mode='cycle_2_2' then v_current_date:=v_current_date+case when mod(v_last_fixed_sequence,2)=1 then 1 else 3 end;
      else
        v_template_index:=case when v_structure_mode='cycle' and v_template_count>0 then mod(v_last_fixed_sequence-1,v_template_count)+1 else v_last_fixed_sequence end;
        select numbered.rest_days_after into v_rest_days_after from (
          select row_number() over(order by pw.position,w.position)::integer sequence_number,w.rest_days_after
          from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id where pw.program_id=v_program_id
        ) numbered where numbered.sequence_number=v_template_index;
        v_current_date:=v_current_date+(1+coalesce(v_rest_days_after,1));
      end if;
      if v_current_date<current_date then v_current_date:=current_date; end if;
    end if;
    if v_schedule_mode='weekly_mwf' then while extract(isodow from v_current_date)::integer not in (1,3,5) loop v_current_date:=v_current_date+1; end loop;
    elsif v_schedule_mode='weekly_tts' then while extract(isodow from v_current_date)::integer not in (2,4,6) loop v_current_date:=v_current_date+1; end loop; end if;
    v_new_start_date:=v_current_date;

    for v_scheduled in select sw.id,sw.sequence_number from public.scheduled_workouts sw where sw.user_program_id=v_user_program.id and sw.status='scheduled' and sw.sequence_number>=v_first_future_sequence order by sw.sequence_number loop
      update public.scheduled_workouts set scheduled_date=v_current_date where id=v_scheduled.id;
      if v_schedule_mode='weekly_mwf' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (1,3,5); end loop;
      elsif v_schedule_mode='weekly_tts' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (2,4,6); end loop;
      elsif v_schedule_mode='cycle_2_2' then v_current_date:=v_current_date+case when mod(v_scheduled.sequence_number,2)=1 then 1 else 3 end;
      else
        v_template_index:=case when v_structure_mode='cycle' and v_template_count>0 then mod(v_scheduled.sequence_number-1,v_template_count)+1 else v_scheduled.sequence_number end;
        select numbered.rest_days_after into v_rest_days_after from (
          select row_number() over(order by pw.position,w.position)::integer sequence_number,w.rest_days_after
          from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id where pw.program_id=v_program_id
        ) numbered where numbered.sequence_number=v_template_index;
        v_current_date:=v_current_date+(1+coalesce(v_rest_days_after,1));
      end if;
    end loop;
    update public.user_programs set start_date=case when v_first_future_sequence=1 then v_new_start_date else start_date end,updated_at=now() where id=v_user_program.id;
  end loop;
  return v_program_id;
end; $function$

CREATE OR REPLACE FUNCTION public.start_program(p_program_id uuid, p_start_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid:=auth.uid(); v_user_program_id uuid; v_scheduled_workout_id uuid; v_scheduled_exercise_id uuid;
  v_current_date date:=p_start_date; v_sequence integer:=0; v_cycle integer; v_repeat_total integer:=1;
  v_workout record; v_exercise record; v_set record; v_found_program uuid; v_schedule_mode text; v_structure_mode text; v_cycle_repeat_count integer; v_isodow integer;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_start_date is null then raise exception 'Start date is required' using errcode='22023'; end if;
  if p_start_date<current_date then raise exception 'Start date cannot be in the past' using errcode='22023'; end if;
  select p.id,p.schedule_mode,p.structure_mode,p.cycle_repeat_count into v_found_program,v_schedule_mode,v_structure_mode,v_cycle_repeat_count
  from public.programs p where p.id=p_program_id and p.status<>'archived';
  if v_found_program is null then raise exception 'Program not found or unavailable' using errcode='P0002'; end if;
  v_repeat_total:=case when v_structure_mode='cycle' then greatest(1,v_cycle_repeat_count) else 1 end;
  v_isodow:=extract(isodow from p_start_date)::integer;
  if v_schedule_mode='weekly_mwf' and v_isodow not in (1,3,5) then raise exception 'First workout must be Monday, Wednesday or Friday' using errcode='22023'; end if;
  if v_schedule_mode='weekly_tts' and v_isodow not in (2,4,6) then raise exception 'First workout must be Tuesday, Thursday or Saturday' using errcode='22023'; end if;
  if exists(select 1 from public.user_programs up where up.user_id=v_user_id and up.program_id=p_program_id and up.status in ('active','paused')) then raise exception 'Program is already active' using errcode='23505'; end if;
  insert into public.user_programs(user_id,program_id,status,start_date) values(v_user_id,p_program_id,'active',p_start_date) returning id into v_user_program_id;

  for v_cycle in 1..v_repeat_total loop
    for v_workout in
      select pw.week_number source_week_number,w.id workout_id,w.name workout_name,w.rest_days_after
      from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id
      where pw.program_id=p_program_id order by pw.position,w.position
    loop
      v_sequence:=v_sequence+1;
      insert into public.scheduled_workouts(user_program_id,source_program_workout_id,sequence_number,week_number,cycle_number,workout_name,scheduled_date,status)
      values(v_user_program_id,v_workout.workout_id,v_sequence::smallint,
        case when v_structure_mode='cycle' then v_cycle::smallint else v_workout.source_week_number end,
        case when v_structure_mode='cycle' then v_cycle::smallint else null end,
        v_workout.workout_name,v_current_date,'scheduled') returning id into v_scheduled_workout_id;

      for v_exercise in
        select pwe.id source_id,pwe.exercise_id,pwe.exercise_name_snapshot,pwe.prescription_snapshot,pwe.position
        from public.program_workout_exercises pwe where pwe.workout_id=v_workout.workout_id order by pwe.position
      loop
        insert into public.scheduled_workout_exercises(scheduled_workout_id,source_program_workout_exercise_id,exercise_id,exercise_name_snapshot,prescription_snapshot,position)
        values(v_scheduled_workout_id,v_exercise.source_id,v_exercise.exercise_id,v_exercise.exercise_name_snapshot,v_exercise.prescription_snapshot,v_exercise.position)
        returning id into v_scheduled_exercise_id;
        for v_set in select pes.set_number,pes.reps from public.program_exercise_sets pes where pes.workout_exercise_id=v_exercise.source_id order by pes.set_number loop
          insert into public.scheduled_sets(scheduled_workout_exercise_id,set_number,planned_reps) values(v_scheduled_exercise_id,v_set.set_number,v_set.reps);
        end loop;
      end loop;

      if v_schedule_mode='weekly_mwf' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (1,3,5); end loop;
      elsif v_schedule_mode='weekly_tts' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (2,4,6); end loop;
      elsif v_schedule_mode='cycle_2_2' then v_current_date:=v_current_date+case when mod(v_sequence,2)=1 then 1 else 3 end;
      else v_current_date:=v_current_date+(1+coalesce(v_workout.rest_days_after,1)); end if;
    end loop;
  end loop;
  if v_sequence=0 then raise exception 'Program has no workouts' using errcode='22023'; end if;
  return v_user_program_id;
end; $function$

CREATE OR REPLACE FUNCTION public.change_program_start_date(p_user_program_id uuid, p_start_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid:=auth.uid(); v_program_id uuid; v_schedule_mode text; v_structure_mode text; v_current_date date:=p_start_date;
  v_scheduled record; v_rest_days_after integer; v_isodow integer; v_template_count integer; v_template_index integer;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_start_date is null then raise exception 'Start date is required' using errcode='22023'; end if;
  if p_start_date<current_date then raise exception 'Start date cannot be in the past' using errcode='22023'; end if;
  select up.program_id,p.schedule_mode,p.structure_mode into v_program_id,v_schedule_mode,v_structure_mode
  from public.user_programs up join public.programs p on p.id=up.program_id
  where up.id=p_user_program_id and up.user_id=v_user_id and up.status in ('active','paused');
  if v_program_id is null then raise exception 'Program participation not found or unavailable' using errcode='P0002'; end if;
  if exists(select 1 from public.scheduled_workouts sw join public.workout_sessions ws on ws.scheduled_workout_id=sw.id where sw.user_program_id=p_user_program_id) then raise exception 'Program has already started' using errcode='22023'; end if;
  if exists(select 1 from public.scheduled_workouts sw where sw.user_program_id=p_user_program_id and sw.status<>'scheduled') then raise exception 'Program schedule already contains workout history' using errcode='22023'; end if;
  v_isodow:=extract(isodow from p_start_date)::integer;
  if v_schedule_mode='weekly_mwf' and v_isodow not in (1,3,5) then raise exception 'First workout must be Monday, Wednesday or Friday' using errcode='22023'; end if;
  if v_schedule_mode='weekly_tts' and v_isodow not in (2,4,6) then raise exception 'First workout must be Tuesday, Thursday or Saturday' using errcode='22023'; end if;
  select count(*) into v_template_count from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id where pw.program_id=v_program_id;

  for v_scheduled in select sw.id,sw.sequence_number from public.scheduled_workouts sw where sw.user_program_id=p_user_program_id order by sw.sequence_number loop
    update public.scheduled_workouts set scheduled_date=v_current_date where id=v_scheduled.id;
    if v_schedule_mode='weekly_mwf' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (1,3,5); end loop;
    elsif v_schedule_mode='weekly_tts' then loop v_current_date:=v_current_date+1; exit when extract(isodow from v_current_date)::integer in (2,4,6); end loop;
    elsif v_schedule_mode='cycle_2_2' then v_current_date:=v_current_date+case when mod(v_scheduled.sequence_number,2)=1 then 1 else 3 end;
    else
      v_template_index:=case when v_structure_mode='cycle' and v_template_count>0 then mod(v_scheduled.sequence_number-1,v_template_count)+1 else v_scheduled.sequence_number end;
      select numbered.rest_days_after into v_rest_days_after from (
        select row_number() over(order by pw.position,w.position)::integer sequence_number,w.rest_days_after
        from public.program_weeks pw join public.program_workouts w on w.week_id=pw.id where pw.program_id=v_program_id
      ) numbered where numbered.sequence_number=v_template_index;
      v_current_date:=v_current_date+(1+coalesce(v_rest_days_after,1));
    end if;
  end loop;
  update public.user_programs set start_date=p_start_date,updated_at=now() where id=p_user_program_id and user_id=v_user_id;
  return p_user_program_id;
end; $function$

CREATE OR REPLACE FUNCTION public.resume_program(p_user_program_id uuid, p_resume_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_program_id uuid;
  v_schedule_mode text;
  v_structure_mode text;
  v_first_sequence integer;
  v_current_date date := p_resume_date;
  v_template_count integer;
  v_template_index integer;
  v_rest_days_after integer;
  v_isodow integer;
  v_row record;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_resume_date is null then
    raise exception 'Resume date is required' using errcode = '22023';
  end if;
  if p_resume_date < current_date then
    raise exception 'Resume date cannot be in the past' using errcode = '22023';
  end if;

  select up.program_id, p.schedule_mode, p.structure_mode
  into v_program_id, v_schedule_mode, v_structure_mode
  from public.user_programs up
  join public.programs p on p.id = up.program_id
  where up.id = p_user_program_id
    and up.user_id = v_user_id
    and up.status = 'paused'
  for update of up;

  if v_program_id is null then
    raise exception 'Paused program participation not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.workout_sessions ws
    join public.scheduled_workouts sw on sw.id = ws.scheduled_workout_id
    where sw.user_program_id = p_user_program_id
      and ws.user_id = v_user_id
      and ws.status = 'active'
  ) then
    raise exception 'Cannot resume program during an active workout' using errcode = '22023';
  end if;

  select min(sw.sequence_number)
  into v_first_sequence
  from public.scheduled_workouts sw
  where sw.user_program_id = p_user_program_id
    and sw.status = 'scheduled';

  if v_first_sequence is null then
    raise exception 'Program has no remaining scheduled workouts' using errcode = '22023';
  end if;

  v_isodow := extract(isodow from p_resume_date)::integer;
  if v_schedule_mode = 'weekly_mwf' and v_isodow not in (1, 3, 5) then
    raise exception 'First workout must be Monday, Wednesday or Friday' using errcode = '22023';
  end if;
  if v_schedule_mode = 'weekly_tts' and v_isodow not in (2, 4, 6) then
    raise exception 'First workout must be Tuesday, Thursday or Saturday' using errcode = '22023';
  end if;

  select count(*)
  into v_template_count
  from public.program_weeks pw
  join public.program_workouts w on w.week_id = pw.id
  where pw.program_id = v_program_id;

  for v_row in
    select sw.id, sw.sequence_number, sw.status
    from public.scheduled_workouts sw
    where sw.user_program_id = p_user_program_id
      and sw.sequence_number >= v_first_sequence
    order by sw.sequence_number
  loop
    if v_row.status = 'scheduled' then
      update public.scheduled_workouts
      set scheduled_date = v_current_date
      where id = v_row.id;
    end if;

    if v_schedule_mode = 'weekly_mwf' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (1, 3, 5);
      end loop;
    elsif v_schedule_mode = 'weekly_tts' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (2, 4, 6);
      end loop;
    elsif v_schedule_mode = 'cycle_2_2' then
      v_current_date := v_current_date + case when mod(v_row.sequence_number, 2) = 1 then 1 else 3 end;
    else
      v_template_index := case
        when v_structure_mode = 'cycle' and v_template_count > 0
          then mod(v_row.sequence_number - 1, v_template_count) + 1
        else v_row.sequence_number
      end;

      select numbered.rest_days_after
      into v_rest_days_after
      from (
        select row_number() over (order by pw.position, w.position)::integer as sequence_number,
               w.rest_days_after
        from public.program_weeks pw
        join public.program_workouts w on w.week_id = pw.id
        where pw.program_id = v_program_id
      ) numbered
      where numbered.sequence_number = v_template_index;

      v_current_date := v_current_date + (1 + coalesce(v_rest_days_after, 1));
    end if;
  end loop;

  update public.user_programs
  set status = 'active',
      start_date = case when v_first_sequence = 1 then p_resume_date else start_date end,
      updated_at = now()
  where id = p_user_program_id
    and user_id = v_user_id;

  return p_user_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_program(p_user_program_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  perform 1
  from public.user_programs up
  where up.id = p_user_program_id
    and up.user_id = v_user_id
    and up.status in ('active', 'paused')
  for update;

  if not found then
    raise exception 'Active or paused program participation not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.workout_sessions ws
    join public.scheduled_workouts sw on sw.id = ws.scheduled_workout_id
    where sw.user_program_id = p_user_program_id
      and ws.user_id = v_user_id
      and ws.status = 'active'
  ) then
    raise exception 'Cannot complete program during an active workout' using errcode = '22023';
  end if;

  update public.scheduled_workouts
  set status = 'cancelled'
  where user_program_id = p_user_program_id
    and status = 'scheduled';

  update public.user_programs
  set status = 'completed',
      completed_at = now(),
      updated_at = now()
  where id = p_user_program_id
    and user_id = v_user_id;

  return p_user_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reschedule_scheduled_workout(p_scheduled_workout_id uuid, p_new_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_user_program_id uuid;
  v_program_id uuid;
  v_sequence_number integer;
  v_schedule_mode text;
  v_structure_mode text;
  v_previous_date date;
  v_current_date date := p_new_date;
  v_template_count integer;
  v_template_index integer;
  v_rest_days_after integer;
  v_isodow integer;
  v_row record;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_new_date is null then raise exception 'New workout date is required' using errcode = '22023'; end if;
  if p_new_date < current_date then raise exception 'New workout date cannot be in the past' using errcode = '22023'; end if;

  select sw.user_program_id, sw.sequence_number, up.program_id, p.schedule_mode, p.structure_mode
  into v_user_program_id, v_sequence_number, v_program_id, v_schedule_mode, v_structure_mode
  from public.scheduled_workouts sw
  join public.user_programs up on up.id = sw.user_program_id
  join public.programs p on p.id = up.program_id
  where sw.id = p_scheduled_workout_id
    and sw.status = 'scheduled'
    and up.user_id = v_user_id
    and up.status = 'active'
  for update of sw, up;

  if v_user_program_id is null then
    raise exception 'Active scheduled workout not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.workout_sessions ws
    join public.scheduled_workouts sw on sw.id = ws.scheduled_workout_id
    where sw.user_program_id = v_user_program_id
      and ws.user_id = v_user_id
      and ws.status = 'active'
  ) then
    raise exception 'Cannot reschedule during an active workout' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.sequence_number > v_sequence_number
      and sw.status in ('completed', 'skipped')
  ) then
    raise exception 'Cannot reschedule before later workout history' using errcode = '22023';
  end if;

  select max(sw.scheduled_date)
  into v_previous_date
  from public.scheduled_workouts sw
  where sw.user_program_id = v_user_program_id
    and sw.sequence_number < v_sequence_number
    and sw.status <> 'cancelled';

  if v_previous_date is not null and p_new_date <= v_previous_date then
    raise exception 'New workout date must be after the previous workout' using errcode = '22023';
  end if;

  v_isodow := extract(isodow from p_new_date)::integer;
  if v_schedule_mode = 'weekly_mwf' and v_isodow not in (1, 3, 5) then
    raise exception 'Workout date must be Monday, Wednesday or Friday' using errcode = '22023';
  end if;
  if v_schedule_mode = 'weekly_tts' and v_isodow not in (2, 4, 6) then
    raise exception 'Workout date must be Tuesday, Thursday or Saturday' using errcode = '22023';
  end if;

  select count(*)
  into v_template_count
  from public.program_weeks pw
  join public.program_workouts w on w.week_id = pw.id
  where pw.program_id = v_program_id;

  for v_row in
    select sw.id, sw.sequence_number, sw.status
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.sequence_number >= v_sequence_number
    order by sw.sequence_number
  loop
    if v_row.status = 'scheduled' then
      update public.scheduled_workouts
      set scheduled_date = v_current_date
      where id = v_row.id;
    end if;

    if v_schedule_mode = 'weekly_mwf' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (1, 3, 5);
      end loop;
    elsif v_schedule_mode = 'weekly_tts' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (2, 4, 6);
      end loop;
    elsif v_schedule_mode = 'cycle_2_2' then
      v_current_date := v_current_date + case when mod(v_row.sequence_number, 2) = 1 then 1 else 3 end;
    else
      v_template_index := case
        when v_structure_mode = 'cycle' and v_template_count > 0
          then mod(v_row.sequence_number - 1, v_template_count) + 1
        else v_row.sequence_number
      end;

      select numbered.rest_days_after
      into v_rest_days_after
      from (
        select row_number() over(order by pw.position, w.position)::integer as sequence_number,
               w.rest_days_after
        from public.program_weeks pw
        join public.program_workouts w on w.week_id = pw.id
        where pw.program_id = v_program_id
      ) numbered
      where numbered.sequence_number = v_template_index;

      v_current_date := v_current_date + (1 + coalesce(v_rest_days_after, 1));
    end if;
  end loop;

  update public.user_programs
  set start_date = case when v_sequence_number = 1 then p_new_date else start_date end,
      updated_at = now()
  where id = v_user_program_id and user_id = v_user_id;

  return p_scheduled_workout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.skip_scheduled_workout(p_scheduled_workout_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_user_program_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;

  select sw.user_program_id
  into v_user_program_id
  from public.scheduled_workouts sw
  join public.user_programs up on up.id = sw.user_program_id
  where sw.id = p_scheduled_workout_id
    and sw.status = 'scheduled'
    and up.user_id = v_user_id
    and up.status = 'active'
  for update of sw, up;

  if v_user_program_id is null then
    raise exception 'Active scheduled workout not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.workout_sessions ws
    where ws.scheduled_workout_id = p_scheduled_workout_id
      and ws.user_id = v_user_id
      and ws.status = 'active'
  ) then
    raise exception 'Cannot skip an active workout' using errcode = '22023';
  end if;

  update public.scheduled_workouts
  set status = 'skipped'
  where id = p_scheduled_workout_id and status = 'scheduled';

  if not exists (
    select 1
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.status = 'scheduled'
  ) then
    update public.user_programs
    set status = 'completed', completed_at = now(), updated_at = now()
    where id = v_user_program_id and user_id = v_user_id;
  else
    update public.user_programs
    set updated_at = now()
    where id = v_user_program_id and user_id = v_user_id;
  end if;

  return p_scheduled_workout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_workout_session_exercises(p_workout_session_id uuid, p_ordered_exercise_ids uuid[], p_scope text DEFAULT 'session'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_scheduled_workout_id uuid;
  v_user_program_id uuid;
  v_source_program_workout_id uuid;
  v_count integer;
  v_distinct_count integer;
  v_item uuid;
  v_position integer := 0;
  v_source_order uuid[];
  v_future record;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_scope not in ('session', 'program') then
    raise exception 'Invalid reorder scope' using errcode = '22023';
  end if;
  if p_ordered_exercise_ids is null or cardinality(p_ordered_exercise_ids) = 0 then
    raise exception 'Exercise order is required' using errcode = '22023';
  end if;

  select ws.scheduled_workout_id, sw.user_program_id, sw.source_program_workout_id
    into v_scheduled_workout_id, v_user_program_id, v_source_program_workout_id
  from public.workout_sessions ws
  join public.scheduled_workouts sw on sw.id = ws.scheduled_workout_id
  where ws.id = p_workout_session_id
    and ws.user_id = v_user_id
    and ws.status = 'active';

  if v_scheduled_workout_id is null then
    raise exception 'Active workout session not found or access denied' using errcode = 'P0002';
  end if;

  select count(*) into v_count
  from public.workout_session_exercises
  where workout_session_id = p_workout_session_id;

  select count(distinct value) into v_distinct_count
  from unnest(p_ordered_exercise_ids) as value;

  if cardinality(p_ordered_exercise_ids) <> v_count or v_distinct_count <> v_count then
    raise exception 'Exercise order must contain every session exercise exactly once' using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(p_ordered_exercise_ids) as requested(id)
    where not exists (
      select 1 from public.workout_session_exercises wse
      where wse.id = requested.id and wse.workout_session_id = p_workout_session_id
    )
  ) then
    raise exception 'Exercise order contains an invalid session exercise' using errcode = '22023';
  end if;

  update public.workout_session_exercises
  set position = position + 1000
  where workout_session_id = p_workout_session_id;

  v_position := 0;
  foreach v_item in array p_ordered_exercise_ids loop
    v_position := v_position + 1;
    update public.workout_session_exercises
    set position = v_position
    where id = v_item and workout_session_id = p_workout_session_id;
  end loop;

  if p_scope = 'program' then
    if v_source_program_workout_id is null then
      raise exception 'This workout is not linked to a reusable program workout' using errcode = '22023';
    end if;

    select array_agg(swe.source_program_workout_exercise_id order by requested.ordinality)
      into v_source_order
    from unnest(p_ordered_exercise_ids) with ordinality as requested(id, ordinality)
    join public.workout_session_exercises wse on wse.id = requested.id
    join public.scheduled_workout_exercises swe on swe.id = wse.source_scheduled_workout_exercise_id;

    if v_source_order is null
       or cardinality(v_source_order) <> v_count
       or exists (select 1 from unnest(v_source_order) source_id where source_id is null) then
      raise exception 'Unable to map this session order back to the program snapshot' using errcode = '22023';
    end if;

    for v_future in
      select sw.id
      from public.scheduled_workouts sw
      where sw.user_program_id = v_user_program_id
        and sw.source_program_workout_id = v_source_program_workout_id
        and sw.status = 'scheduled'
        and sw.id <> v_scheduled_workout_id
        and sw.scheduled_date >= current_date
      order by sw.sequence_number
    loop
      if (select count(*) from public.scheduled_workout_exercises swe where swe.scheduled_workout_id = v_future.id) <> v_count then
        continue;
      end if;

      update public.scheduled_workout_exercises
      set position = position + 1000
      where scheduled_workout_id = v_future.id;

      v_position := 0;
      foreach v_item in array v_source_order loop
        v_position := v_position + 1;
        update public.scheduled_workout_exercises
        set position = v_position
        where scheduled_workout_id = v_future.id
          and source_program_workout_exercise_id = v_item;
      end loop;
    end loop;
  end if;

  return p_workout_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fill_program_set_reps_from_prescription()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_prescription text;
  v_match text[];
begin
  if new.reps is not null then
    return new;
  end if;

  select pwe.prescription_snapshot
    into v_prescription
  from public.program_workout_exercises pwe
  where pwe.id = new.workout_exercise_id;

  if nullif(btrim(v_prescription), '') is null then
    return new;
  end if;

  v_match := regexp_match(v_prescription, '(\d+)\s*[\*xх×]\s*(\d+)', 'i');
  if v_match is not null then
    new.reps := greatest(1, least(999, v_match[2]::integer));
    return new;
  end if;

  v_match := regexp_match(v_prescription, 'по\s*(\d+)', 'i');
  if v_match is not null then
    new.reps := greatest(1, least(999, v_match[1]::integer));
    return new;
  end if;

  v_match := regexp_match(v_prescription, '(\d+)\s*-\s*(\d+)', 'i');
  if v_match is not null then
    new.reps := greatest(1, least(999, v_match[1]::integer));
    return new;
  end if;

  v_match := regexp_match(v_prescription, '^\s*(\d+)\s*(?:$|раз|повтор|повт|шаг|на(?:\s|$))', 'i');
  if v_match is not null then
    new.reps := greatest(1, least(999, v_match[1]::integer));
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reschedule_scheduled_workout_scoped(p_scheduled_workout_id uuid, p_new_date date, p_scope text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_user_program_id uuid;
  v_program_id uuid;
  v_sequence_number integer;
  v_schedule_mode text;
  v_structure_mode text;
  v_current_status text;
  v_has_later_completed boolean := false;
  v_previous_date date;
  v_next_date date;
  v_current_date date := p_new_date;
  v_template_count integer;
  v_template_index integer;
  v_rest_days_after integer;
  v_isodow integer;
  v_row record;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_new_date is null then raise exception 'New workout date is required' using errcode = '22023'; end if;
  if p_new_date < current_date then raise exception 'New workout date cannot be in the past' using errcode = '22023'; end if;
  if p_scope not in ('single', 'tail') then raise exception 'Invalid reschedule scope' using errcode = '22023'; end if;

  select sw.user_program_id, sw.sequence_number, sw.status, up.program_id, p.schedule_mode, p.structure_mode
  into v_user_program_id, v_sequence_number, v_current_status, v_program_id, v_schedule_mode, v_structure_mode
  from public.scheduled_workouts sw
  join public.user_programs up on up.id = sw.user_program_id
  join public.programs p on p.id = up.program_id
  where sw.id = p_scheduled_workout_id
    and sw.status in ('scheduled', 'skipped')
    and up.user_id = v_user_id
    and up.status = 'active'
  for update of sw, up;

  if v_user_program_id is null then
    raise exception 'Active editable workout not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.workout_sessions ws
    join public.scheduled_workouts sw on sw.id = ws.scheduled_workout_id
    where sw.user_program_id = v_user_program_id
      and ws.user_id = v_user_id
      and ws.status = 'active'
  ) then
    raise exception 'Cannot reschedule during an active workout' using errcode = '22023';
  end if;

  select exists (
    select 1
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.sequence_number > v_sequence_number
      and sw.status = 'completed'
  ) into v_has_later_completed;

  if v_current_status = 'scheduled' and v_has_later_completed then
    raise exception 'Cannot reschedule before later workout history' using errcode = '22023';
  end if;
  if p_scope = 'tail' and v_has_later_completed then
    raise exception 'Cannot reschedule before later workout history' using errcode = '22023';
  end if;

  select max(sw.scheduled_date)
  into v_previous_date
  from public.scheduled_workouts sw
  where sw.user_program_id = v_user_program_id
    and sw.sequence_number < v_sequence_number
    and sw.status <> 'cancelled';

  if not (v_current_status = 'skipped' and v_has_later_completed) then
    if v_previous_date is not null and p_new_date <= v_previous_date then
      raise exception 'New workout date must be after the previous workout' using errcode = '22023';
    end if;
  end if;

  if p_scope = 'single' then
    if not (v_current_status = 'skipped' and v_has_later_completed) then
      select min(sw.scheduled_date)
      into v_next_date
      from public.scheduled_workouts sw
      where sw.user_program_id = v_user_program_id
        and sw.sequence_number > v_sequence_number
        and sw.status <> 'cancelled';

      if v_next_date is not null and p_new_date >= v_next_date then
        raise exception 'New workout date must be before the next workout' using errcode = '22023';
      end if;
    end if;

    update public.scheduled_workouts
    set scheduled_date = p_new_date,
        status = 'scheduled'
    where id = p_scheduled_workout_id
      and status in ('scheduled', 'skipped');

    update public.user_programs
    set start_date = case when v_sequence_number = 1 and not v_has_later_completed then p_new_date else start_date end,
        updated_at = now()
    where id = v_user_program_id and user_id = v_user_id;

    return p_scheduled_workout_id;
  end if;

  v_isodow := extract(isodow from p_new_date)::integer;
  if v_schedule_mode = 'weekly_mwf' and v_isodow not in (1, 3, 5) then
    raise exception 'Workout date must be Monday, Wednesday or Friday' using errcode = '22023';
  end if;
  if v_schedule_mode = 'weekly_tts' and v_isodow not in (2, 4, 6) then
    raise exception 'Workout date must be Tuesday, Thursday or Saturday' using errcode = '22023';
  end if;

  select count(*)
  into v_template_count
  from public.program_weeks pw
  join public.program_workouts w on w.week_id = pw.id
  where pw.program_id = v_program_id;

  for v_row in
    select sw.id, sw.sequence_number, sw.status
    from public.scheduled_workouts sw
    where sw.user_program_id = v_user_program_id
      and sw.sequence_number >= v_sequence_number
    order by sw.sequence_number
  loop
    if v_row.status in ('scheduled', 'skipped') then
      update public.scheduled_workouts
      set scheduled_date = v_current_date,
          status = 'scheduled'
      where id = v_row.id;
    end if;

    if v_schedule_mode = 'weekly_mwf' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (1, 3, 5);
      end loop;
    elsif v_schedule_mode = 'weekly_tts' then
      loop
        v_current_date := v_current_date + 1;
        exit when extract(isodow from v_current_date)::integer in (2, 4, 6);
      end loop;
    elsif v_schedule_mode = 'cycle_2_2' then
      v_current_date := v_current_date + case when mod(v_row.sequence_number, 2) = 1 then 1 else 3 end;
    else
      v_template_index := case
        when v_structure_mode = 'cycle' and v_template_count > 0
          then mod(v_row.sequence_number - 1, v_template_count) + 1
        else v_row.sequence_number
      end;

      select numbered.rest_days_after
      into v_rest_days_after
      from (
        select row_number() over(order by pw.position, w.position)::integer as sequence_number,
               w.rest_days_after
        from public.program_weeks pw
        join public.program_workouts w on w.week_id = pw.id
        where pw.program_id = v_program_id
      ) numbered
      where numbered.sequence_number = v_template_index;

      v_current_date := v_current_date + (1 + coalesce(v_rest_days_after, 1));
    end if;
  end loop;

  update public.user_programs
  set start_date = case when v_sequence_number = 1 then p_new_date else start_date end,
      updated_at = now()
  where id = v_user_program_id and user_id = v_user_id;

  return p_scheduled_workout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.pause_workout(p_scheduled_workout_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_session_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;

  update public.workout_sessions ws
  set active_duration_seconds = ws.active_duration_seconds + greatest(0, floor(extract(epoch from (now() - ws.started_at)))::integer),
      paused_at = now(),
      updated_at = now()
  where ws.user_id = v_user_id
    and ws.scheduled_workout_id = p_scheduled_workout_id
    and ws.status = 'active'
    and ws.paused_at is null
  returning ws.id into v_session_id;

  if v_session_id is null then
    select ws.id into v_session_id
    from public.workout_sessions ws
    where ws.user_id=v_user_id and ws.scheduled_workout_id=p_scheduled_workout_id and ws.status='active' and ws.paused_at is not null
    limit 1;
  end if;
  if v_session_id is null then raise exception 'Active workout session not found' using errcode='P0002'; end if;
  return v_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resume_workout(p_scheduled_workout_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_session_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;

  update public.workout_sessions ws
  set started_at = now(), paused_at = null, updated_at = now()
  where ws.user_id=v_user_id
    and ws.scheduled_workout_id=p_scheduled_workout_id
    and ws.status='active'
    and ws.paused_at is not null
  returning ws.id into v_session_id;

  if v_session_id is null then raise exception 'Paused workout session not found' using errcode='P0002'; end if;
  return v_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.pause_program(p_user_program_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid();
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  perform 1 from public.user_programs up where up.id=p_user_program_id and up.user_id=v_user_id and up.status='active' for update;
  if not found then raise exception 'Active program participation not found' using errcode='P0002'; end if;
  if exists (
    select 1 from public.workout_sessions ws join public.scheduled_workouts sw on sw.id=ws.scheduled_workout_id
    where sw.user_program_id=p_user_program_id and ws.user_id=v_user_id and ws.status='active'
  ) then raise exception 'Cannot pause program during an active or paused workout' using errcode='22023'; end if;
  update public.user_programs set status='paused',paused_at=now(),updated_at=now() where id=p_user_program_id and user_id=v_user_id;
  return p_user_program_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_program(p_user_program_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid();
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode='42501'; end if;
  update public.user_programs
  set status='cancelled', updated_at=now()
  where id=p_user_program_id and user_id=v_user_id and status in ('active','paused');
  if not found then raise exception 'Active program participation not found' using errcode='P0002'; end if;
  update public.scheduled_workouts set status='cancelled'
  where user_program_id=p_user_program_id and status in ('scheduled','skipped');
  return p_user_program_id;
end;
$function$
